/**
 * Art pack manifest: sprite atlases in public/art (generated by scripts/gen-art.py, see docs/ART_PACK.md).
 * Nothing here is required to play: every loader call resolves to null when a file is missing, and callers keep their current look.
 * A clip is a run of frames in an atlas read left to right, top to bottom.
 */

export interface ArtClip {
  id: string
  /** File under public/art. */
  file: string
  /** Atlas grid. */
  cols: number
  rows: number
  /** First frame (index into the grid) and number of frames in the clip. */
  start: number
  frames: number
  /** Playback rate; 0 means a still (pick a frame yourself, e.g. a random smoke puff). */
  fps: number
  /** Pivot inside a frame, 0..1 from the top-left. */
  anchor: readonly [number, number]
  /** True when the pixels are white or a single hue made to be multiplied by a colour. */
  tintable: boolean
  loop: boolean
  /** Atlas tiles seamlessly along this axis (trails, overlays). */
  tile?: 'x' | 'xy'
  /** Shape cue for colour-blind readers, when the clip is colour coded. */
  shapeCue?: string
}

type Opts = Partial<Pick<ArtClip, 'anchor' | 'tintable' | 'loop' | 'tile' | 'shapeCue'>>

const c = (id: string, file: string, cols: number, rows: number, start: number, frames: number, fps: number, o: Opts = {}): ArtClip => ({
  id, file, cols, rows, start, frames, fps,
  anchor: o.anchor ?? [0.5, 0.5], tintable: o.tintable ?? false, loop: o.loop ?? false, tile: o.tile, shapeCue: o.shapeCue,
})

