const BY_ID = new Map(ART_CLIPS.map((a) => [a.id, a]))
export const artClip = (id: string): ArtClip | undefined => BY_ID.get(id)

export const artUrl = (file: string) => `${import.meta.env.BASE_URL}art/${file}`

/** Source rectangle of one frame of a clip inside its atlas image. Looping clips wrap, others hold their last frame. */
export function frameRect(clip: ArtClip, frame: number, imgW: number, imgH: number) {
  const f = Math.floor(frame)
  const n = clip.loop ? ((f % clip.frames) + clip.frames) % clip.frames : Math.min(Math.max(f, 0), clip.frames - 1)
  const idx = clip.start + n
  const w = imgW / clip.cols
  const h = imgH / clip.rows
  return { sx: (idx % clip.cols) * w, sy: Math.floor(idx / clip.cols) * h, sw: w, sh: h }
}

/** Frame to show `elapsedMs` after a clip started. */
export const frameAt = (clip: ArtClip, elapsedMs: number) => (clip.fps > 0 ? Math.floor((elapsedMs / 1000) * clip.fps) : 0)

// ---- loader ---------------------------------------------------------------------------------------------

const cache = new Map<string, Promise<HTMLImageElement | null>>()
const ready = new Map<string, HTMLImageElement>()

/** Loads an atlas file once. Resolves to null (never rejects) when it is missing, blocked or there is no DOM. */
export function loadArtFile(file: string): Promise<HTMLImageElement | null> {
  let p = cache.get(file)
  if (!p) {
    p = new Promise<HTMLImageElement | null>((resolve) => {
      if (typeof Image === 'undefined') return resolve(null)
      const img = new Image()
      img.decoding = 'async'
      img.onload = () => { ready.set(file, img); resolve(img) }
      img.onerror = () => resolve(null)
      img.src = artUrl(file)
    })
    cache.set(file, p)
  }
  return p
}

/** Loads the atlas a clip lives in. Null when the clip is unknown or the file is missing. */
export async function loadArt(id: string): Promise<{ clip: ArtClip; image: HTMLImageElement } | null> {
  const clip = BY_ID.get(id)
  if (!clip) return null
  const image = await loadArtFile(clip.file)
  return image ? { clip, image } : null
}

/** Atlas for a clip if already loaded, else null (a draw loop skips the sprite and keeps its old look). The first ask starts the load. */
export function getArt(id: string): { clip: ArtClip; image: HTMLImageElement } | null {
  const clip = BY_ID.get(id)
  if (!clip) return null
  const image = ready.get(clip.file)
  if (!image) { void loadArtFile(clip.file); return null }
  return { clip, image }
}

/** Warms files in idle time, staggered, so first use does not hitch. Pass ids to limit it to the atlases those need. */
export function preloadArt(ids?: readonly string[]): void {
  const names = ids ? ids.map((i) => BY_ID.get(i)?.file) : ART_CLIPS.map((a) => a.file)
  const files = [...new Set(names.filter((f): f is string => !!f))]
  const idle = (cb: () => void) => (typeof requestIdleCallback === 'function' ? requestIdleCallback(cb) : setTimeout(cb, 300))
  files.forEach((f, i) => idle(() => { setTimeout(() => void loadArtFile(f), i * 150) }))
}
